#define HASH_SIZE (1 << 22)
#define HASH_MASK (HASH_SIZE - 1)

typedef struct Entry {
    long long key;
    long long count;
    int used;
} Entry;

Entry table[HASH_SIZE];

void hash_insert(long long key, long long cnt) {
    unsigned int h = (unsigned int)((key * 2654435761ULL) & HASH_MASK);
    while (table[h].used && table[h].key != key) {
        h = (h + 1) & HASH_MASK;
    }
    if (!table[h].used) {
        table[h].used = 1;
        table[h].key = key;
        table[h].count = 0;
    }
    table[h].count += cnt;
}

long long hash_get(long long key) {
    unsigned int h = (unsigned int)((key * 2654435761ULL) & HASH_MASK);
    while (table[h].used && table[h].key != key) {
        h = (h + 1) & HASH_MASK;
    }
    if (!table[h].used) return 0;
    return table[h].count;
}

int main() {
    int N;
    long long V;
    scanf("%d %lld", &N, &V);

    long long *a = (long long*)malloc(N * sizeof(long long));
    long long *b = (long long*)malloc(N * sizeof(long long));
    long long *c = (long long*)malloc(N * sizeof(long long));
    long long *d = (long long*)malloc(N * sizeof(long long));

    for (int i = 0; i < N; i++) scanf("%lld", &a[i]);
    for (int i = 0; i < N; i++) scanf("%lld", &b[i]);
    for (int i = 0; i < N; i++) scanf("%lld", &c[i]);
    for (int i = 0; i < N; i++) scanf("%lld", &d[i]);

    memset(table, 0, sizeof(table));

    // Insert all a[i] + b[j] sums
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            hash_insert(a[i] + b[j], 1);
        }
    }

    long long ans = 0;

    // For each c[k] + d[l], look up V - (c[k]+d[l])
    for (int k = 0; k < N; k++) {
        for (int l = 0; l < N; l++) {
            long long need = V - c[k] - d[l];
            ans += hash_get(need);
        }
    }

    printf("%lld\n", ans);

    free(a); free(b); free(c); free(d);
    return 0;
}

