#define MAX_SUM 200000

int main() {
    int N, V;
    scanf("%d %d", &N, &V);

    int *a = (int*)malloc(N * sizeof(int));
    int *b = (int*)malloc(N * sizeof(int));
    int *c = (int*)malloc(N * sizeof(int));
    int *d = (int*)malloc(N * sizeof(int));

    for (int i = 0; i < N; i++) scanf("%d", &a[i]);
    for (int i = 0; i < N; i++) scanf("%d", &b[i]);
    for (int i = 0; i < N; i++) scanf("%d", &c[i]);
    for (int i = 0; i < N; i++) scanf("%d", &d[i]);

    int *sumCountAB = (int*)calloc(MAX_SUM + 1, sizeof(int));
    int *sumCountCD = (int*)calloc(MAX_SUM + 1, sizeof(int));

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            int s = a[i] + b[j];
            if (s <= MAX_SUM) sumCountAB[s]++;
        }
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            int s = c[i] + d[j];
            if (s <= MAX_SUM) sumCountCD[s]++;
        }
    }

    long long result = 0;
    for (int s = 0; s <= MAX_SUM; s++) {
        if (sumCountAB[s] > 0) {
            int need = V - s;
            if (need >= 0 && need <= MAX_SUM) {
                result += (long long)sumCountAB[s] * sumCountCD[need];
            }
        }
    }

    printf("%lld\n", result);

    free(a); free(b); free(c); free(d);
    free(sumCountAB); free(sumCountCD);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    long long V;
    if (scanf("%d %lld", &N, &V) != 2) return 0;

    long long *A = (long long *)malloc((size_t)N * sizeof(long long));
    long long *B = (long long *)malloc((size_t)N * sizeof(long long));
    long long *C = (long long *)malloc((size_t)N * sizeof(long long));
    long long *D = (long long *)malloc((size_t)N * sizeof(long long));

    for (int i = 0; i < N; i++) scanf("%lld", &A[i]);
    for (int i = 0; i < N; i++) scanf("%lld", &B[i]);
    for (int i = 0; i < N; i++) scanf("%lld", &C[i]);
    for (int i = 0; i < N; i++) scanf("%lld", &D[i]);

    long long M = (long long)N * N;
    long long *CD = (long long *)malloc((size_t)M * sizeof(long long));

    long long idx = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            CD[idx++] = C[i] + D[j];
        }
    }

    qsort(CD, (size_t)M, sizeof(long long), cmp_ll);

    long long ans = 0;

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            long long need = V - A[i] - B[j];

            long long l = 0, r = M;
            while (l < r) {
                long long mid = l + (r - l) / 2;
                if (CD[mid] < need) l = mid + 1;
                else r = mid;
            }
            long long left = l;

            l = 0; r = M;
            while (l < r) {
                long long mid = l + (r - l) / 2;
                if (CD[mid] <= need) l = mid + 1;
                else r = mid;
            }
            long long right = l;

            ans += (right - left);
        }
    }

    printf("%lld\n", ans);

    free(A);
    free(B);
    free(C);
    free(D);
    free(CD);

    return 0;
}

