import java.io.*;
import java.util.*;

public class Main {
    // Fast input
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        long V = fs.nextLong();

        long[] A = new long[N];
        long[] B = new long[N];
        long[] C = new long[N];
        long[] D = new long[N];

        for (int i = 0; i < N; i++) A[i] = fs.nextLong();
        for (int i = 0; i < N; i++) B[i] = fs.nextLong();
        for (int i = 0; i < N; i++) C[i] = fs.nextLong();
        for (int i = 0; i < N; i++) D[i] = fs.nextLong();

        // Count all sums of A[i] + B[j]
        HashMap<Long, Long> countAB = new HashMap<>();
        for (int i = 0; i < N; i++) {
            long ai = A[i];
            for (int j = 0; j < N; j++) {
                long sum = ai + B[j];
                countAB.put(sum, countAB.getOrDefault(sum, 0L) + 1L);
            }
        }

        long ans = 0;
        for (int i = 0; i < N; i++) {
            long ci = C[i];
            for (int j = 0; j < N; j++) {
                long need = V - (ci + D[j]);
                ans += countAB.getOrDefault(need, 0L);
            }
        }

        System.out.println(ans);
    }
}
